"""Optional-cone port checks against frozen FP32 and controlled CPU references."""
import json
import subprocess
from pathlib import Path
import numpy as np

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
OUT = HERE / "validation"


def read_config(path):
    return dict(line.split("=", 1) for line in path.read_text().splitlines() if "=" in line)


def run(config, name, executable):
    config = dict(config)
    config["output_dir"] = str(OUT / name)
    path = OUT / f"{name}.cfg"
    path.write_text("".join(f"{key}={value}\n" for key, value in config.items()))
    subprocess.run([str(executable), "--config", str(path)], check=True, timeout=300)
    return OUT / name


def final(folder):
    return np.load(sorted(folder.glob("snapshot_*.npy"))[-1])


def main():
    base = read_config(OUT / "inductive_split_gpu.cfg")
    absent = run(base, "cme_absent_fp32", HERE / "mhd_cuda_fp32_cme")
    assert np.array_equal(final(OUT / "inductive_split_fp32"), final(absent)), "Absent cone changed FP32 state"
    cones = OUT / "synthetic_cones.csv"
    cones.write_text("start_day,end_day,lon_rad,lat_rad,halfwidth_rad,speed_kms,density_factor,temperature_factor\n"
                     ".02,.25,1.2,.1,.6,950,4,2\n.05,.2,1.5,.05,.5,1100,3,1\n")
    base["cme_boundary_csv"] = str(cones)
    cpu = run(base, "cme_tiny_cpu", HERE.parent / "cme_cpu/mhd_solver_cme_split")
    gpu = run(base, "cme_tiny_fp32", HERE / "mhd_cuda_fp32_cme")
    a, b = final(cpu).astype(float), final(gpu).astype(float)
    result = {"absent_cones_exact_float32_snapshot": True,
              "tiny_CME_Linf_relative_to_field_Linf":
                  (np.max(abs(b-a), axis=(0, 1, 2))/(np.max(abs(a), axis=(0, 1, 2))+1e-30)).tolist(),
              "CPU_statistics": json.loads((cpu / "statistics.json").read_text()),
              "FP32_statistics": json.loads((gpu / "statistics.json").read_text())}
    (OUT / "cme_fp32_agreement.json").write_text(json.dumps(result, indent=2)+"\n")
    assert max(result["tiny_CME_Linf_relative_to_field_Linf"]) < 1e-3
    base = read_config(ROOT / "results/cme_coarse_split/run.cfg")
    base["flux_variant"] = "split_llf"
    gpu = run(base, "production_cme_coarse_fp32", HERE / "mhd_cuda_fp32_cme")
    subprocess.run(["python", str(HERE.parent / "experiments/compare_variant.py"),
                    str(ROOT / "results/cme_coarse_split"), str(gpu),
                    str(OUT / "production_cme_coarse_fp32_GTI_comparison.json")], check=True)


if __name__ == "__main__":
    main()
"}}
